import http.server, os
class H(http.server.SimpleHTTPRequestHandler):
    # SPA fallback like netlify.toml: route paths (/interests/) get index.html,
    # real files and missing assets (with an extension) behave normally
    def send_head(self):
        p = self.translate_path(self.path)
        route = not os.path.splitext(self.path.split('?')[0])[1]
        if route and not os.path.isfile(p) and not os.path.isfile(os.path.join(p, 'index.html')):
            self.path = '/index.html'
        return super().send_head()
    def end_headers(self):
        self.send_header('Cache-Control', 'no-store')
        super().end_headers()
http.server.ThreadingHTTPServer(('', 2020), H).serve_forever()
